  onClearAllPoints?: (itemId: string) => void;
  onCommitPointChanges?: (itemId: string) => void;
  onAutoAlign?: (sourceId: string, targetId: string) => Promise<void>;
  onClosePanel?: () => void;
  onFloatingAction?: (id: string, action: string) => void;
}

