    { cat: '电力激活', tags: ['接通电源 → 屏幕亮起', '开启开关 → 核心发光', '感应器激活 → 改变CMF'] },
    { cat: '环境碰撞', tags: ['置于雨中 → 表面凝聚水珠', '激光照射 → 切割火花', '置入熔岩 → 边缘发红熔化'] },
];

const PropertiesPanel: React.FC<PropertiesPanelProps> = ({ 
