        { label: '复位模型状态', cmd: '重置所有设置' },
        { label: '物理爆炸展开', cmd: '将模型爆炸 60%' },
        { label: '聚焦选中零件', cmd: '高亮选中零件' },
        { label: '零件平铺模式', cmd: '开启平铺模式 100%' },
